class Solution {
public:
    double maxPrice(std::vector<std::vector<int>>& items, int capacity) {
        long long total_w = 0;
        for (const auto& it : items) total_w += it[1];
        if (total_w < capacity) return -1.0;

        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
            return (long long)a[0] * b[1] > (long long)b[0] * a[1];
        });
        double ans = 0.0;
        int rem = capacity;
        for (const auto& it : items) {
            int p = it[0], w = it[1];
            if (rem <= w) {
                ans += (double)p / w * rem;
                return ans;
            } else {
                ans += p;
                rem -= w;
            }
        }
        return ans;
    }
};

class Solution {
    public double maxPrice(int[][] items, int capacity) {
        long totalW = 0;
        for (int[] it : items) totalW += it[1];
        if (totalW < capacity) return -1.0;

        java.util.Arrays.sort(items, (a, b) -> {
            long diff = (long)b[0] * a[1] - (long)a[0] * b[1];
            return Long.compare(diff, 0);
        });
        double ans = 0.0;
        int rem = capacity;
        for (int[] it : items) {
            int p = it[0], w = it[1];
            if (rem <= w) {
                ans += (double)p / w * rem;
                return ans;
            } else {
                ans += p;
                rem -= w;
            }
        }
        return ans;
    }
}

var maxPrice = function(items, capacity) {
    let totalW = 0;
    for (const [, w] of items) totalW += w;
    if (totalW < capacity) return -1.0;

    items.sort((a, b) => (b[0] / b[1]) - (a[0] / a[1]));
    let ans = 0.0;
    let rem = capacity;
    for (const [p, w] of items) {
        if (rem <= w) {
            ans += (p / w) * rem;
            return ans;
        } else {
            ans += p;
            rem -= w;
        }
    }
    return ans;
};
